import{_ as i,o as s,c as l,ag as e}from"./chunks/framework.DWOJQht4.js";const k=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1792598800000}'),t={name:"guide/faq.md"};function n(h,a,o,p,d,c){return s(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="部署相关" tabindex="-1">部署相关 <a class="header-anchor" href="#部署相关" aria-label="Permalink to &quot;部署相关&quot;">​</a></h2><h3 id="q-当前推荐的生产部署方式是什么" tabindex="-1">Q: 当前推荐的生产部署方式是什么？ <a class="header-anchor" href="#q-当前推荐的生产部署方式是什么" aria-label="Permalink to &quot;Q: 当前推荐的生产部署方式是什么？&quot;">​</a></h3><p>A: 当前主推方案是：</p><ul><li><code>systemd + 单二进制</code></li><li>前端已内嵌进服务二进制</li><li>数据库按环境选择 SQLite 或 MySQL</li></ul><p>这也是当前文档默认描述的生产部署口径。</p><h3 id="q-支持哪些操作系统" tabindex="-1">Q: 支持哪些操作系统？ <a class="header-anchor" href="#q-支持哪些操作系统" aria-label="Permalink to &quot;Q: 支持哪些操作系统？&quot;">​</a></h3><p>A: 生产环境推荐 Linux，并使用 <code>systemd</code> 托管服务：</p><ul><li>✅ Ubuntu 22.04+</li><li>✅ Debian 12+</li><li>✅ CentOS Stream 9+</li></ul><p>理论上开发环境也可在 macOS / Windows 运行，但生产环境不作为主推方案。</p><h3 id="q-为什么不再推荐-docker-compose-一键部署" tabindex="-1">Q: 为什么不再推荐 Docker Compose 一键部署？ <a class="header-anchor" href="#q-为什么不再推荐-docker-compose-一键部署" aria-label="Permalink to &quot;Q: 为什么不再推荐 Docker Compose 一键部署？&quot;">​</a></h3><p>A: 当前交付方式已经改为 <strong>单二进制 + 内嵌前端</strong>，部署链路更短：</p><ul><li>不需要单独部署前端</li><li>不强制绑定容器编排</li><li>更适合直接接入现有 Linux 生产主机和 <code>systemd</code></li></ul><p>Docker 仍可用于题目运行时和动态靶机场景，但不再作为平台主服务的默认生产部署方式。</p><h3 id="q-前端现在怎么部署" tabindex="-1">Q: 前端现在怎么部署？ <a class="header-anchor" href="#q-前端现在怎么部署" aria-label="Permalink to &quot;Q: 前端现在怎么部署？&quot;">​</a></h3><p>A: 不需要单独部署。<br> 前端静态资源已经打包进服务二进制，访问：</p><ul><li><code>/</code></li><li><code>/admin</code></li></ul><p>都会由同一个后端服务直接返回。</p><h3 id="q-数据库必须用-mysql-吗" tabindex="-1">Q: 数据库必须用 MySQL 吗？ <a class="header-anchor" href="#q-数据库必须用-mysql-吗" aria-label="Permalink to &quot;Q: 数据库必须用 MySQL 吗？&quot;">​</a></h3><p>A: 不是。</p><p>当前支持通过 <code>DATABASE_URI</code> 配置多种数据库，生产场景常见两种：</p><ul><li><code>SQLite</code>：单机、轻量、开箱即用</li><li><code>MySQL</code>：更适合正式生产环境</li></ul><h3 id="q-如何更新到新版本" tabindex="-1">Q: 如何更新到新版本？ <a class="header-anchor" href="#q-如何更新到新版本" aria-label="Permalink to &quot;Q: 如何更新到新版本？&quot;">​</a></h3><p>A:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 停服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudctf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 替换二进制</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new-cloudctf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/cloudctf/bin/cloudctf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/cloudctf/bin/cloudctf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 启动服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudctf</span></span></code></pre></div><p>更新前建议：</p><ol><li>备份数据库</li><li>备份上传目录与备份目录</li><li>记录当前配置文件</li></ol><h2 id="功能相关" tabindex="-1">功能相关 <a class="header-anchor" href="#功能相关" aria-label="Permalink to &quot;功能相关&quot;">​</a></h2><h3 id="q-支持哪些题目类型" tabindex="-1">Q: 支持哪些题目类型？ <a class="header-anchor" href="#q-支持哪些题目类型" aria-label="Permalink to &quot;Q: 支持哪些题目类型？&quot;">​</a></h3><p>A: 支持：</p><ul><li>Web</li><li>Pwn</li><li>Reverse</li><li>Crypto</li><li>Misc</li><li>理论题 / 考试</li><li>动态靶机题</li><li>漏洞复现环境</li></ul><h3 id="q-动态环境为什么还依赖-docker" tabindex="-1">Q: 动态环境为什么还依赖 Docker？ <a class="header-anchor" href="#q-动态环境为什么还依赖-docker" aria-label="Permalink to &quot;Q: 动态环境为什么还依赖 Docker？&quot;">​</a></h3><p>A: 平台主服务已经不依赖 Docker 部署，但 <strong>动态靶机 / 漏洞环境运行时</strong> 仍依赖 Docker 或对应虚拟化资源。这是“平台部署方式”和“题目运行环境”两个不同层面。</p><h3 id="q-如何导入-vulhub-ctfdb-模板" tabindex="-1">Q: 如何导入 Vulhub / CTFDB 模板？ <a class="header-anchor" href="#q-如何导入-vulhub-ctfdb-模板" aria-label="Permalink to &quot;Q: 如何导入 Vulhub / CTFDB 模板？&quot;">​</a></h3><p>A: 通过管理后台的资源仓库与模板同步能力完成。<br> 建议部署完成后先配置好虚拟化主机、出口地址、资源仓库，再执行同步。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><h3 id="q-服务启动失败怎么办" tabindex="-1">Q: 服务启动失败怎么办？ <a class="header-anchor" href="#q-服务启动失败怎么办" aria-label="Permalink to &quot;Q: 服务启动失败怎么办？&quot;">​</a></h3><p>A:</p><ol><li>查看 <code>systemd</code> 状态：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudctf</span></span></code></pre></div><ol start="2"><li>查看实时日志：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudctf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><ol start="3"><li>检查配置文件：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/cloudctf/config/cloudctf.env</span></span></code></pre></div><ol start="4"><li>检查端口占用：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lntp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8005</span></span></code></pre></div><p>如果日志中出现：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>invalid configuration: ALLOWED_ORIGINS must not contain * in production</span></span></code></pre></div><p>说明当前配置了 <code>APP_ENV=production</code>，但 <code>ALLOWED_ORIGINS</code> 为空、未配置或仍为默认 <code>*</code>。生产环境必须改成实际访问源，例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ALLOWED_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://ctf.example.com</span></span></code></pre></div><p>没有域名时可先使用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ALLOWED_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://服务器IP:8005</span></span></code></pre></div><h3 id="q-页面能打开-但后台静态资源异常" tabindex="-1">Q: 页面能打开，但后台静态资源异常？ <a class="header-anchor" href="#q-页面能打开-但后台静态资源异常" aria-label="Permalink to &quot;Q: 页面能打开，但后台静态资源异常？&quot;">​</a></h3><p>A: 先确认当前运行的二进制是否为最新版本。因为前端资源已经内嵌进二进制，页面资源是否更新取决于你实际启动的是不是新产物，而不是单独的前端目录。</p><h3 id="q-api-返回-500-怎么办" tabindex="-1">Q: API 返回 500 怎么办？ <a class="header-anchor" href="#q-api-返回-500-怎么办" aria-label="Permalink to &quot;Q: API 返回 500 怎么办？&quot;">​</a></h3><p>A:</p><ol><li>查看 <code>journalctl -u cloudctf -f</code></li><li>检查 <code>DATABASE_URI</code></li><li>检查上传目录、备份目录是否有写权限</li><li>如涉及动态靶机，再检查 Docker 与虚拟化配置</li></ol><h3 id="q-动态靶机启动失败怎么办" tabindex="-1">Q: 动态靶机启动失败怎么办？ <a class="header-anchor" href="#q-动态靶机启动失败怎么办" aria-label="Permalink to &quot;Q: 动态靶机启动失败怎么办？&quot;">​</a></h3><p>A:</p><ol><li>检查 Docker 是否正常运行</li><li>检查主机节点配置是否正确</li><li>检查模板端口、镜像、Dockerfile、Compose 文件是否完整</li><li>检查出口地址是否可达</li><li>查看容器日志与平台日志</li></ol><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><h3 id="q-如何获取技术支持" tabindex="-1">Q: 如何获取技术支持？ <a class="header-anchor" href="#q-如何获取技术支持" aria-label="Permalink to &quot;Q: 如何获取技术支持？&quot;">​</a></h3><p>A:</p><ul><li>文档：站内文档</li><li>GitHub Issues：提交问题</li><li>Email：<code>5829662@qq.com</code></li></ul><h3 id="q-是否支持定制部署" tabindex="-1">Q: 是否支持定制部署？ <a class="header-anchor" href="#q-是否支持定制部署" aria-label="Permalink to &quot;Q: 是否支持定制部署？&quot;">​</a></h3><p>A: 支持，但当前公开文档默认只维护主线生产方案，也就是 <code>systemd + 单二进制</code>。如果你们内部有额外的发布链路，建议在此基础上做局部扩展，而不是继续维护完全独立的旧部署体系。</p>`,66)])])}const u=i(t,[["render",n]]);export{k as __pageData,u as default};
